{"action": "sql", "sql": "WITH race AS (
  SELECT raceid FROM races WHERE date = '1983-07-16'
),
participants AS (
  SELECT driverid, time FROM results WHERE raceid = (SELECT raceid FROM race)
)
SELECT 
  ROUND(100.0 * COUNT(CASE WHEN time IS NOT NULL THEN 1 END) / COUNT(*), 2) AS completion_rate
FROM participants;"}

{"action": "sql", "sql": "SELECT COUNT(DISTINCT p.id) AS patient_count
FROM public.patient p
WHERE EXISTS (
    SELECT 1 FROM public.laboratory l
    WHERE l.id = p.id AND l.cpk < 250
)
AND EXISTS (
    SELECT 1 FROM public.examination e
    WHERE e.id = p.id AND (e.kct = '+' OR e.rvvt = '+' OR e.lac = '+')
);"}

{"action": "sql", "sql": "WITH driver AS (
  SELECT driverid FROM public.drivers WHERE forename = 'Lewis' AND surname = 'Hamilton'
),
race AS (
  SELECT raceid FROM public.races WHERE name = 'Malaysian Grand Prix' AND year = 2009
)
SELECT AVG(l.milliseconds) AS average_lap_time_ms
FROM public.laptimes l
JOIN driver d ON l.driverid = d.driverid
JOIN race r ON l.raceid = r.raceid;"}

{"action": "sql", "sql": "WITH target_post AS (
  SELECT id FROM posts WHERE title = 'Why square the difference instead of taking the absolute value in standard deviation?'
),
editors AS (
  SELECT DISTINCT userid FROM posthistory WHERE postid = (SELECT id FROM target_post)
)
SELECT c.id, c.postid, c.score, c.text, c.creationdate, c.userid, c.userdisplayname
FROM comments c
JOIN editors e ON c.userid = e.userid
ORDER BY c.creationdate;"}

{"action": "sql", "sql": "WITH carcinogenic_molecules AS (
    SELECT molecule_id FROM public.molecule WHERE label = '+'
)
SELECT 
    (SELECT COUNT(*) FROM public.bond WHERE bond_type = '-' AND molecule_id IN (SELECT molecule_id FROM carcinogenic_molecules))::numeric /
    NULLIF((SELECT COUNT(*) FROM public.atom WHERE molecule_id IN (SELECT molecule_id FROM carcinogenic_molecules)), 0) AS average_single_bonds_per_atom;"}
